import {address,safeLabel,escapeHTML as e,https,iso,priority,aggregateEligibility,ALERT_TYPES,exportWatchlist,importWatchlist} from './aggregator-core.js';
const $=id=>document.getElementById(id),key='am_aggregator_v1';let state={wallets:[],results:{},interests:[]},campaigns=[],filters={};
try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved){const data=importWatchlist(saved);state={...state,...data,results:saved.results||{},interests:saved.interests||[],quests:saved.quests||{}}}}catch{notify('Data lokal tidak terbaca. Import backup bila tersedia.');}
const save=()=>localStorage.setItem(key,JSON.stringify({...exportWatchlist(state.wallets,state.legacy),results:state.results,interests:state.interests,quests:state.quests}));
function notify(text){$('status').textContent=text;setTimeout(()=>{if($('status').textContent===text)$('status').textContent=''},7000);}
const date=v=>v?new Date(v).toLocaleString('id-ID'):'Belum diketahui';
function link(u,label){try{return `<a href="${e(https(u))}" target="_blank" rel="noopener noreferrer">${e(label||u)}</a>`}catch{return 'URL tidak valid'}}
function initData(){return window.Telegram?.WebApp?.initData||'';}
async function api(path,options={}){const headers={...(options.body?{'Content-Type':'application/json'}:{}),...(initData()?{'X-Telegram-Init-Data':initData()}:{}),...options.headers};const r=await fetch('/api/aggregator'+path,{...options,headers,signal:AbortSignal.timeout(45000)});const data=await r.json();if(!r.ok)throw Error(data.error||'Layanan tidak tersedia');return data;}
function guard(fn){return async event=>{event?.preventDefault();const b=event?.submitter||(event?.currentTarget?.tagName==='BUTTON'?event.currentTarget:null);if(b)b.disabled=true;try{await fn(event)}catch(err){notify(err.message)}finally{if(b)b.disabled=false}}}
function walletKey(w){return w.chain+':'+w.address;}
function wallets(){const container=$('wallet-list');container.innerHTML=state.wallets.map((w,i)=>{const result=state.results[walletKey(w)];return `<article class="card"><h3>${e(w.label||'Wallet tanpa label')}</h3><p class="meta">${e(w.chain)}<br>${e(w.address)}</p><p>Scan terakhir: ${e(date(result?.portfolio?.scanned_at))}<br>Saldo utama: ${e(result?.portfolio?.balance??'Belum diketahui')} ${e(result?.portfolio?.balance_unit||'')}</p><p class="meta">Aktivitas protokol: ${e((result?.result?.protocol_activity||[]).map(a=>a.rule_type+': '+a.value).join(', ')||'Belum tersedia')}</p><label>Campaign untuk scan<select data-campaign="${i}">${campaigns.filter(c=>(c.chain.includes(w.chain)||c.chain.includes('offchain'))).map(c=>`<option value="${e(c.id)}">${e(c.name)}</option>`).join('')}</select></label><div class="actions"><button data-scan="${i}">Scan address-only</button><button data-remove="${i}">Hapus lokal</button></div><div data-result="${i}">${result?.result?renderResult(result.result):''}</div></article>`}).join('')||'<p>Belum ada alamat di perangkat ini.</p>';
 container.querySelectorAll('[data-remove]').forEach(b=>b.onclick=guard(()=>{const w=state.wallets.splice(Number(b.dataset.remove),1)[0];delete state.results[walletKey(w)];save();wallets()}));
 container.querySelectorAll('[data-scan]').forEach(b=>b.onclick=guard(async()=>{const i=Number(b.dataset.scan),w=state.wallets[i],id=container.querySelector(`[data-campaign="${i}"]`).value;if(!id)throw Error('Pilih campaign yang sesuai chain terlebih dahulu.');const result=await api('/scan',{method:'POST',body:JSON.stringify({chain:w.chain,address:w.address,campaign_id:id})});const previous=state.results[walletKey(w)];state.results[walletKey(w)]={...result,campaigns:{...previous?.campaigns,...(previous?.result?{[previous.result.campaign_id]:previous.result}:{}),[id]:result.result}};save();wallets();renderCampaigns();notify('Scan selesai; hasil disimpan lokal.')}));
}
function renderResult(r){return `<div class="result"><h4>Eligibility: ${e(r.status)}</h4><p>${e(r.notice)}</p><ul>${r.rules.map(v=>`<li><b>${e(v.rule_type)} · ${e(v.evaluation_status)}</b><br>${e(v.human_reason)}<br><small>${e(date(v.evaluated_at))}</small><br>${v.evidence_refs.map(ref=>link(ref.source_url,'Sumber · '+ref.source_type)).join(' · ')}</li>`).join('')}</ul><h4>Claim: ${e(r.claim.status)}</h4><p>${e(r.claim.human_reason)}</p><p>${link(r.claim.official_url,'Periksa di sumber resmi')}<br>Chain: ${e(r.claim.chain)}<br>Distributor: ${e(r.claim.distributor||'Belum tersedia')}<br>Deadline: ${e(date(r.claim.deadline))}</p><small>${e(date(r.claim.checked_at))}</small></div>`;}
async function load(){const params=new URLSearchParams(filters);$('registry-state').textContent='Memuat registry…';try{const data=await api('/campaigns?'+params);campaigns=data.campaigns;$('registry-state').textContent=campaigns.length?campaigns.length+' campaign · status terpisah dari eligibility wallet':'Belum ada campaign dari sumber resmi yang dikonfigurasi. Tidak ada data demo yang dianggap aktif.';renderCampaigns();wallets();}catch(err){$('registry-state').textContent='Registry belum tersedia: '+err.message;}}
function renderCampaigns(){$('campaign-list').innerHTML=campaigns.map(c=>{const known=Object.values(state.results).flatMap(v=>v.campaigns?.[c.id]?.rules||v.result?.campaign_id===c.id&&v.result.rules||[]);const p=priority(c,known,state.interests);return `<article class="card"><span class="badge ${e(c.effective_status)}">${e(c.effective_status)}</span><span class="badge">${e(c.category)}</span><h3>${e(c.name)}</h3><p>${e(c.description.slice(0,220))}</p><p class="meta">${e(c.chain.join(' · '))}<br>Snapshot: ${e(date(c.snapshot_at))}<br>Claim deadline: ${e(date(c.claim_deadline_at))}<br>Gas: ${c.gas_cost_estimate==null?'Belum diketahui':e(c.gas_cost_estimate)+' USD (estimasi)'}<br>KYC: ${e(c.kyc_requirement)}</p><p>${e(p.label)} · pribadi</p><label class="check"><input type="checkbox" data-interest="${e(c.category)}" ${state.interests.includes(c.category)?'checked':''}>Saya tertarik kategori ini</label><button data-detail="${e(c.id)}">Lihat syarat & evidence</button></article>`}).join('');$('campaign-list').querySelectorAll('[data-detail]').forEach(b=>b.onclick=guard(()=>detail(b.dataset.detail)));$('campaign-list').querySelectorAll('[data-interest]').forEach(b=>b.onchange=()=>{state.interests=b.checked?[...new Set([...state.interests,b.dataset.interest])]:state.interests.filter(v=>v!==b.dataset.interest);save();renderCampaigns()});}
async function detail(id){const data=await api('/campaigns/'+encodeURIComponent(id)),c=data.campaign;$('detail-body').innerHTML=`<span class="badge">${e(c.effective_status)}</span><h2>${e(c.name)}</h2><p>${e(c.description)}</p><p>${c.official_urls.map(u=>link(u,'Sumber resmi')).join(' · ')}</p><dl>${['snapshot_at','activity_start_at','activity_end_at','claim_opens_at','claim_deadline_at','last_verified_at'].map(k=>`<dt>${e(k)}</dt><dd>${e(date(c[k]))}</dd>`).join('')}</dl><h3>Aturan eligibility</h3><ul>${c.eligibility_rules.map(r=>`<li>${e(r.rule_type)}<pre>${e(JSON.stringify(r.parameters,null,2))}</pre></li>`).join('')}</ul><h3>Catatan risiko</h3><ul>${c.risk_flags.map(f=>`<li>${e(f)}</li>`).join('')}</ul><h3>Quest & poin pribadi</h3><p>Checklist dan poin yang dicatat sendiri belum terverifikasi.</p><form id="quest-local"><label>Quest atau catatan<input name="note" maxlength="200"></label><label>Poin yang tercatat (manual)<input name="points" type="number" min="0" step="any"></label><button>Simpan catatan lokal</button></form><p id="quest-note"></p><h3>Timeline evidence</h3><ol class="timeline">${data.timeline.map(t=>`<li>${link(t.source_url,t.source_type)} · ${e(t.verified_by)}<br>${e(date(t.captured_at))}<br>${e(t.event_type)}<br>${e(t.note)}</li>`).join('')}</ol>`;
 const notes=state.quests?.[id];if(notes)$('quest-note').textContent=notes.note+' · '+notes.points+' poin (manual, belum terverifikasi)';$('quest-local').onsubmit=guard(event=>{const f=new FormData(event.target),note=safeLabel(f.get('note')),points=String(f.get('points'));state.quests={...state.quests,[id]:{note,points,updated_at:iso(),verified:false}};save();$('quest-note').textContent=note+' · '+points+' poin (manual, belum terverifikasi)'});$('campaign-detail').showModal();}
$('close-detail').onclick=()=>$('campaign-detail').close();
$('filters').onsubmit=guard(async event=>{filters=Object.fromEntries([...new FormData(event.target)].filter(([,v])=>v));for(const k of ['deadline_before','snapshot_before'])if(filters[k])filters[k]+='T23:59:59.999Z';await load()});$('refresh').onclick=guard(load);
$('wallet-form').onsubmit=guard(event=>{const f=new FormData(event.target),chain=f.get('chain'),w={chain,address:address(f.get('address').trim(),chain),label:safeLabel(f.get('label'))};if(state.wallets.some(v=>walletKey(v)===walletKey(w)))throw Error('Alamat sudah ada dalam watchlist.');if(state.wallets.length>=100)throw Error('Batas 100 alamat.');state.wallets.push(w);save();event.target.reset();wallets();notify('Alamat disimpan lokal.');});
$('export').onclick=guard(()=>{const data={...exportWatchlist(state.wallets,state.legacy),results:state.results,interests:state.interests,quests:state.quests};const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='airdrop-museum-aggregator.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)});
$('import').onchange=guard(async event=>{const file=event.target.files[0];if(!file||file.size>1000000)throw Error('Backup tidak valid atau melebihi 1 MB.');const raw=JSON.parse(await file.text()),data=importWatchlist(raw);state={...state,...data,results:raw.kind==='aggregator-core'?raw.results||{}:state.results,quests:raw.kind==='aggregator-core'?raw.quests||{}:state.quests,interests:raw.kind==='aggregator-core'?raw.interests||[]:state.interests};save();wallets();notify('Backup berhasil diimpor; data lama dipertahankan.');});
function telegramRequired(){if(!initData())throw Error('Buka melalui Mini App Telegram terverifikasi.');}
$('sync').onclick=guard(async()=>{telegramRequired();if(!$('sync-consent').checked)throw Error('Persetujuan sinkronisasi belum diberikan.');await api('/import',{method:'POST',body:JSON.stringify({consent_sync:true,data:exportWatchlist(state.wallets)})});notify('Watchlist tersinkron. Scan berkala dijalankan oleh server.');});
$('pull').onclick=guard(async()=>{telegramRequired();const data=await api('/wallets');state.wallets=data.wallets.map(w=>({chain:w.chain,address:address(w.address,w.chain),label:safeLabel(w.label)}));for(const w of data.wallets.slice(0,20)){const stored=await api('/results?wallet_id='+encodeURIComponent(w.id));const byCampaign={};for(const r of stored.eligibility){const group=byCampaign[r.campaign_id]??={rules:[],seen:new Set()};if(group.seen.has(r.rule_id))continue;group.seen.add(r.rule_id);group.rules.push({...r,parameters:JSON.parse(r.parameters),evidence_refs:JSON.parse(r.evidence_refs)});}const results={};for(const [id,group] of Object.entries(byCampaign)){const c=campaigns.find(v=>v.id===id),claim=stored.claims.find(r=>r.campaign_id===id);results[id]={campaign_id:id,rules:group.rules,status:aggregateEligibility(group.rules),claim:claim?JSON.parse(claim.payload):{status:'unknown',human_reason:'Belum diperiksa',official_url:c?.official_urls[0],chain:w.chain},notice:'Hasil server perlu diverifikasi ulang.'};}const last=Object.values(results)[0];state.results[walletKey(w)]={portfolio:stored.snapshots[0]?JSON.parse(stored.snapshots[0].payload):null,result:last||null,campaigns:results};}save();wallets();renderCampaigns();notify('Watchlist dan hasil scan server disimpan lokal (maksimal 20 wallet per pemuatan).');});
$('erase-local').onclick=guard(()=>{state={wallets:[],results:{},interests:[]};localStorage.removeItem(key);wallets();notify('Data aggregator lokal dihapus.');});
$('erase-server').onclick=guard(async()=>{telegramRequired();await api('/privacy',{method:'DELETE'});notify('Watchlist, hasil, dan preferensi aggregator server dihapus.');});
const alertNames={new_campaign:'Campaign baru',snapshot_7d:'Snapshot dalam 7 hari',claim_open:'Claim dibuka',deadline_72h:'Deadline dalam 72 jam',eligibility_change:'Eligibility berubah',new_quest:'Quest baru',source_changed:'Sumber resmi berubah'};
$('alert-types').innerHTML=ALERT_TYPES.map(t=>`<label class="check"><input type="checkbox" name="event" value="${t}" checked>${e(alertNames[t])}</label>`).join('');
$('alert-form').onsubmit=guard(async event=>{telegramRequired();const enabled=$('alert-consent').checked;await api('/preferences',{method:'PUT',body:JSON.stringify({enabled,consent_alerts:enabled,filters,event_types:new FormData(event.target).getAll('event')})});notify(enabled?'Alert Telegram diaktifkan.':'Alert Telegram dinonaktifkan.');});
$('alert-history').onclick=guard(async()=>{telegramRequired();const data=await api('/alerts');$('alert-list').innerHTML=data.alerts.map(a=>{const p=JSON.parse(a.payload);return `<article class="card"><b>${e(p.campaign)}</b><p>${e(p.reason)} · ${e(a.status)}</p>${link(p.source_url,'Sumber resmi')}<p>${e(date(a.created_at))}</p></article>`}).join('')||'<p>Belum ada alert.</p>';});
await load();const selected=new URLSearchParams(location.search).get('campaign');if(selected)try{await detail(selected)}catch(err){notify(err.message)}
if(initData())try{const p=await api('/preferences');filters=p.filters||{};for(const [k,v] of Object.entries(filters)){const field=$('filters').elements.namedItem(k);if(field)field.value=k.endsWith('_before')?String(v).slice(0,10):v;}await load();$('alert-consent').checked=p.enabled;$('alert-types').querySelectorAll('input').forEach(b=>b.checked=p.event_types.includes(b.value))}catch{/* Keep local mode available. */}
